        pigeonVar_channel.setMessageHandler(null);
      } else {
        pigeonVar_channel.setMessageHandler((Object? message) async {
          final List<Object?> args = message! as List<Object?>;
          final bool arg_isFullscreen = args[0]! as bool;
          try {
            await api.onWindowFullscreen(arg_isFullscreen);
            return wrapResponse(empty: true);
          } on PlatformException catch (e) {
            return wrapResponse(error: e);
          } catch (e) {
            return wrapResponse(
              error: PlatformException(code: 'error', message: e.toString()),
            );
          }
        });
      }
    }
  }

  /// Registers [api] for Native Interop callers under [name], or the default
  /// instance when [name] is omitted or empty, and returns [api].
  static PlayerFlutterApi implement(PlayerFlutterApi api, {String name = defaultInstanceName}) {
    return PlayerFlutterApiRegistrar().register(
      api,
      name: name.isEmpty ? defaultInstanceName : name,
    );
  }
}
